mapper.select:
SELECT r.*, b.book_name
FROM t_borrow_record r LEFT JOIN t_book b ON r.book_id = b.id
WHERE r.id = #{id}

SELECT COUNT(*) FROM t_borrow_record
WHERE user_id = #{userId}
  AND borrow_date >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

SELECT COUNT(*) FROM t_borrow_record
WHERE user_id = #{userId} AND status = 2
  AND DATEDIFF(NOW(), due_date) >= #{days}
